package edu.smartstudy.quiz;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import edu.smartstudy.material.*;import edu.smartstudy.user.UserRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.Positive;import java.util.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/api/v1/quizzes")public class QuizController{private final QuizRepository quizzes;private final QuizAttemptRepository attempts;private final MaterialRepository materials;private final UserRepository users;private final ObjectMapper json;private final RestClient ml;public QuizController(QuizRepository quizzes,QuizAttemptRepository attempts,MaterialRepository materials,UserRepository users,ObjectMapper json,@Value("${app.ml-url}")String mlUrl){this.quizzes=quizzes;this.attempts=attempts;this.materials=materials;this.users=users;this.json=json;ml=RestClient.builder().baseUrl(mlUrl).build();}private Long owner(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();}public record GenerateRequest(@Positive Long materialId){}public record AttemptInput(@jakarta.validation.constraints.NotEmpty List<String> answers){}@GetMapping public List<Map<String,Object>> list(Authentication a){return quizzes.findTop100ByOwnerIdOrderByCreatedAtDesc(owner(a)).stream().map(q->Map.<String,Object>of("id",q.getId(),"title",q.getTitle(),"materialId",q.getMaterialId(),"createdAt",q.getCreatedAt())).toList();}@PostMapping("/generate")public ResponseEntity<?> generate(@RequestBody @Valid GenerateRequest input,Authentication a)throws Exception{Long student=owner(a);Material material=materials.findByIdAndOwnerId(input.materialId(),student).orElse(null);if(material==null)return ResponseEntity.notFound().build();if(!"COMPLETED".equals(material.getStatus())||material.getExtractedText()==null)return ResponseEntity.status(409).body(Map.of("error","Wait until this material has finished processing."));Map<?,?> generated=ml.post().uri("/ml/v1/questions").contentType(MediaType.APPLICATION_JSON).body(Map.of("text",material.getExtractedText())).retrieve().body(Map.class);List<Map<String,Object>> questions=json.convertValue(generated.get("questions"),new TypeReference<>(){});if(questions==null||questions.isEmpty())return ResponseEntity.status(422).body(Map.of("error",Objects.toString(generated.get("notice"),"This material did not contain enough clear definitions to build a quiz.")));Quiz quiz=quizzes.save(new Quiz(student,material.getId(),"Quiz: "+material.getTitle(),json.writeValueAsString(questions)));return ResponseEntity.status(201).body(view(quiz,student));}@GetMapping("/{id}")public ResponseEntity<?> detail(@PathVariable Long id,Authentication a){return quizzes.findByIdAndOwnerId(id,owner(a)).<ResponseEntity<?>>map(q->ResponseEntity.ok(view(q,owner(a)))).orElseGet(()->ResponseEntity.notFound().build());}private Map<String,Object> view(Quiz q,Long owner){try{List<Map<String,Object>> source=json.readValue(q.getQuestionsJson(),new TypeReference<>(){});List<Map<String,Object>> safe=source.stream().map(x->{Map<String,Object> out=new LinkedHashMap<>();for(String key:List.of("question","options","explanation","difficulty","source_reference"))if(x.containsKey(key))out.put(key,x.get(key));return out;}).toList();return Map.of("id",q.getId(),"title",q.getTitle(),"materialId",q.getMaterialId(),"createdAt",q.getCreatedAt(),"questions",safe,"attempts",attempts.findTop30ByQuizIdAndStudentIdOrderBySubmittedAtDesc(q.getId(),owner));}catch(Exception e){throw new IllegalStateException("Could not read quiz",e);}}@PostMapping("/{id}/attempts")public ResponseEntity<?> submit(@PathVariable Long id,@RequestBody @Valid AttemptInput input,Authentication a)throws Exception{Long student=owner(a);Quiz quiz=quizzes.findByIdAndOwnerId(id,student).orElse(null);if(quiz==null)return ResponseEntity.notFound().build();List<Map<String,Object>> questions=json.readValue(quiz.getQuestionsJson(),new TypeReference<>(){});if(input.answers().size()!=questions.size())return ResponseEntity.badRequest().body(Map.of("error","Submit one answer for each question."));int score=0;List<Map<String,Object>> results=new ArrayList<>();for(int i=0;i<questions.size();i++){var q=questions.get(i);String correct=Objects.toString(q.get("correct_answer"),"");String selected=input.answers().get(i);boolean right=correct.equals(selected);if(right)score++;results.add(Map.of("question",q.get("question"),"selectedAnswer",selected,"correctAnswer",correct,"correct",right,"explanation",q.get("explanation"),"sourceReference",q.get("source_reference")));}QuizAttempt attempt=attempts.save(new QuizAttempt(id,student,score,questions.size(),json.writeValueAsString(input.answers())));return ResponseEntity.status(201).body(Map.of("attemptId",attempt.getId(),"score",score,"total",questions.size(),"accuracyPercent",Math.round(100.0*score/questions.size()),"results",results,"notice","Generated questions and explanations are drafts; confirm them against the original material."));}}
